from first_place import *
import first_place
ORIGINAL=Two.both

def run_speed(p,save=None):
 factors,params=p
 with open(os.devnull,'w') as out,contextlib.redirect_stdout(out):
  step=[0]
  def scaled(self,right,left,n=60,pitch=.4,hold=10,rot=True):
   i=step[0];step[0]+=1;f=factors[min(i,len(factors)-1)]
   return ORIGINAL(self,right,left,n=max(10,int(n*f)),pitch=pitch,hold=max(2,int(hold*f)),rot=rot)
  Two.both=scaled;first_place.PARAM=np.array(params)
  tr=first_place.place(save=False)
  for t in range(35):
   ac=tr.c.action();tr.actions.append(ac);_,_,done=tr.s.step(ac)
   if done:break
  pos=tr.s.data.body('trophy').xpos.copy();root=tr.s.data.qpos[:3].copy();v=np.linalg.norm(tr.s.data.qvel[:3]);dist=np.linalg.norm(pos-[.75,-.25,1.55])
  score=2-4*dist-max(0,.8-root[2])*3-v*.1-len(tr.actions)*.0001
  if save:tr.save(save);tr.image(save)
  Two.both=ORIGINAL
 return score,p,pos,root,len(tr.actions)
if __name__=='__main__':
 rng=np.random.default_rng(4);par=np.load('/app/output/transfer_search.npz')['params'][:12];ps=[]
 for i in range(180):
  f=rng.uniform(.45,.85);factors=[f]*3+[min(1,f+rng.uniform(.05,.2))]*2+[min(1,f+rng.uniform(.0,.15))]*2+[min(1,f+rng.uniform(.0,.2))]*2+[f]*2
  ps.append((factors,par[i%len(par)]))
 with Pool(12) as pool:
  rs=[]
  for r in pool.imap_unordered(run_speed,ps):
   rs.append(r)
   if r[0]>1.4:print('GOOD',r,flush=True)
 rs.sort(key=lambda r:-r[0]);np.savez('/app/output/speed_search.npz',factors=np.array([r[1][0] for r in rs]),params=np.array([r[1][1] for r in rs]),scores=np.array([r[0] for r in rs]))
 for r in rs[:8]:print(r,flush=True)
 print('BEST',run_speed(rs[0][1],'speed_best'),flush=True)
PY
